import React from 'react';
import { Link, useLocation } from 'react-router-dom';

const AdminNav = () => {
  const { pathname } = useLocation();
  return (
    <nav className="bg-white shadow mb-4">
      <div className="max-w-6xl mx-auto px-4 py-3 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <span className="font-bold text-green-700 text-lg">AgriWatch</span>
          <span className="text-xs text-gray-500 ml-2">Admin</span>
        </div>
        <div className="flex gap-4">
          <Link to="/admin" className={pathname === "/admin" ? "text-green-700 font-semibold" : "text-gray-700 hover:text-green-700"}>Dashboard</Link>
          <Link to="/admin/model-management" className={pathname === "/admin/model-management" ? "text-green-700 font-semibold" : "text-gray-700 hover:text-green-700"}>Models</Link>
          <Link to="/admin/alerts" className={pathname === "/admin/alerts" ? "text-green-700 font-semibold" : "text-gray-700 hover:text-green-700"}>Alerts</Link>
          <Link to="/admin/monitored-farms" className={pathname === "/admin/monitored-farms" ? "text-green-700 font-semibold" : "text-gray-700 hover:text-green-700"}>Farms</Link>
        </div>
      </div>
    </nav>
  );
};

export default AdminNav;
